ALTER TABLE `stock_transactions` MODIFY `type` ENUM('RECEIPT','ISSUE','RETURN','TRANSFER','ADJUSTMENT') NOT NULL;

CREATE TABLE `parts` (`id` VARCHAR(191) NOT NULL, `code` VARCHAR(80) NOT NULL, `name` VARCHAR(160) NOT NULL, `description` VARCHAR(500) NULL, `unit` VARCHAR(20) NOT NULL DEFAULT 'EA', `reorder_level` DECIMAL(18,4) NOT NULL DEFAULT 0, `is_active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `parts_code_key`(`code`), INDEX `parts_name_idx`(`name`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `suppliers` (`id` VARCHAR(191) NOT NULL, `code` VARCHAR(50) NOT NULL, `name` VARCHAR(160) NOT NULL, `phone` VARCHAR(40) NULL, `email` VARCHAR(255) NULL, `address` VARCHAR(255) NULL, `is_active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `suppliers_code_key`(`code`), INDEX `suppliers_name_idx`(`name`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `purchase_orders` (`id` VARCHAR(191) NOT NULL, `order_no` VARCHAR(50) NOT NULL, `supplier_id` VARCHAR(191) NOT NULL, `status` ENUM('DRAFT','SENT','PARTIALLY_RECEIVED','RECEIVED','CANCELLED') NOT NULL DEFAULT 'DRAFT', `ordered_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `notes` VARCHAR(500) NULL, UNIQUE INDEX `purchase_orders_order_no_key`(`order_no`), INDEX `purchase_orders_supplier_id_status_idx`(`supplier_id`,`status`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `purchase_order_lines` (`id` VARCHAR(191) NOT NULL, `purchase_order_id` VARCHAR(191) NOT NULL, `part_id` VARCHAR(191) NOT NULL, `quantity` DECIMAL(18,4) NOT NULL, `unit_cost` DECIMAL(18,4) NULL, UNIQUE INDEX `purchase_order_lines_purchase_order_id_part_id_key`(`purchase_order_id`,`part_id`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `goods_receipts` (`id` VARCHAR(191) NOT NULL, `receipt_no` VARCHAR(50) NOT NULL, `purchase_order_id` VARCHAR(191) NULL, `location_id` VARCHAR(191) NOT NULL, `received_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `received_by_id` VARCHAR(191) NULL, UNIQUE INDEX `goods_receipts_receipt_no_key`(`receipt_no`), INDEX `goods_receipts_location_id_received_at_idx`(`location_id`,`received_at`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `goods_receipt_lines` (`id` VARCHAR(191) NOT NULL, `goods_receipt_id` VARCHAR(191) NOT NULL, `part_id` VARCHAR(191) NOT NULL, `quantity` DECIMAL(18,4) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `parts_requests` (`id` VARCHAR(191) NOT NULL, `request_no` VARCHAR(50) NOT NULL, `branch_id` VARCHAR(191) NOT NULL, `requested_by_id` VARCHAR(191) NULL, `status` ENUM('OPEN','APPROVED','FULFILLED','CANCELLED') NOT NULL DEFAULT 'OPEN', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `parts_requests_request_no_key`(`request_no`), INDEX `parts_requests_branch_id_status_idx`(`branch_id`,`status`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `parts_request_lines` (`id` VARCHAR(191) NOT NULL, `request_id` VARCHAR(191) NOT NULL, `part_id` VARCHAR(191) NOT NULL, `quantity` DECIMAL(18,4) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `parts_issues` (`id` VARCHAR(191) NOT NULL, `issue_no` VARCHAR(50) NOT NULL, `location_id` VARCHAR(191) NOT NULL, `issued_by_id` VARCHAR(191) NULL, `issued_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `parts_issues_issue_no_key`(`issue_no`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `parts_issue_lines` (`id` VARCHAR(191) NOT NULL, `issue_id` VARCHAR(191) NOT NULL, `part_id` VARCHAR(191) NOT NULL, `quantity` DECIMAL(18,4) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `parts_returns` (`id` VARCHAR(191) NOT NULL, `return_no` VARCHAR(50) NOT NULL, `location_id` VARCHAR(191) NOT NULL, `returned_by_id` VARCHAR(191) NULL, `returned_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `parts_returns_return_no_key`(`return_no`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `parts_return_lines` (`id` VARCHAR(191) NOT NULL, `return_id` VARCHAR(191) NOT NULL, `part_id` VARCHAR(191) NOT NULL, `quantity` DECIMAL(18,4) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE `purchase_orders` ADD CONSTRAINT `purchase_orders_supplier_id_fkey` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `purchase_order_lines` ADD CONSTRAINT `purchase_order_lines_purchase_order_id_fkey` FOREIGN KEY (`purchase_order_id`) REFERENCES `purchase_orders`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `purchase_order_lines_part_id_fkey` FOREIGN KEY (`part_id`) REFERENCES `parts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `goods_receipts` ADD CONSTRAINT `goods_receipts_purchase_order_id_fkey` FOREIGN KEY (`purchase_order_id`) REFERENCES `purchase_orders`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT `goods_receipts_location_id_fkey` FOREIGN KEY (`location_id`) REFERENCES `locations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `goods_receipt_lines` ADD CONSTRAINT `goods_receipt_lines_goods_receipt_id_fkey` FOREIGN KEY (`goods_receipt_id`) REFERENCES `goods_receipts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `goods_receipt_lines_part_id_fkey` FOREIGN KEY (`part_id`) REFERENCES `parts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `parts_request_lines` ADD CONSTRAINT `parts_request_lines_request_id_fkey` FOREIGN KEY (`request_id`) REFERENCES `parts_requests`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `parts_request_lines_part_id_fkey` FOREIGN KEY (`part_id`) REFERENCES `parts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `parts_issues` ADD CONSTRAINT `parts_issues_location_id_fkey` FOREIGN KEY (`location_id`) REFERENCES `locations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `parts_issue_lines` ADD CONSTRAINT `parts_issue_lines_issue_id_fkey` FOREIGN KEY (`issue_id`) REFERENCES `parts_issues`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `parts_issue_lines_part_id_fkey` FOREIGN KEY (`part_id`) REFERENCES `parts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `parts_returns` ADD CONSTRAINT `parts_returns_location_id_fkey` FOREIGN KEY (`location_id`) REFERENCES `locations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `parts_return_lines` ADD CONSTRAINT `parts_return_lines_return_id_fkey` FOREIGN KEY (`return_id`) REFERENCES `parts_returns`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `parts_return_lines_part_id_fkey` FOREIGN KEY (`part_id`) REFERENCES `parts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
